{"text":"[Reading 40 lines from start (total: 40 lines, 0 remaining)]\n\n\n\"\"\"\nFederated Learning Worker - เรียนจากมือถือหลายล้านเครื่องโดยไม่ส่งข้อมูลส่วนตัว\nที่ Apple, Google ใช้\nสำหรับ NOVA: เรียนจากพอร์ตลูกค้าหลายคนโดยไม่เห็นพอร์ตจริง\n\"\"\"\nimport random\n\nclass FederatedLearningWorker:\n    def __init__(self, num_clients=100):\n        self.num_clients = num_clients\n        self.global_model = {\"weights\": [0.5, 0.3, 0.2]}\n        \n    def client_train(self, client_id, local_data):\n        # แต่ละเครื่องเทรน local ไม่ส่ง data จริงขึ้น server\n        local_weights = [w + random.uniform(-0.05, 0.05) for w in self.global_model[\"weights\"]]\n        # ส่งแค่ gradient ไม่ใช่ data\n        gradient = [lw - gw for lw, gw in zip(local_weights, self.global_model[\"weights\"])]\n        print(f\"📱 Client {client_id} - Train local {len(local_data)} samples - ส่งแค่ gradient ไม่ส่งพอร์ตจริง\")\n        return gradient\n    \n    def federated_averaging(self, all_gradients):\n        # FedAvg\n        avg_grad = [sum(g[i] for g in all_gradients) / len(all_gradients) for i in range(3)]\n        self.global_model[\"weights\"] = [gw + ag for gw, ag in zip(self.global_model[\"weights\"], avg_grad)]\n        print(f\"🌐 Federated Averaging - {len(all_gradients)} clients -> Global model updated\")\n        print(f\"   New weights: {self.global_model['weights']}\")\n        return self.global_model\n    \n    def run_round(self):\n        grads = []\n        for i in range(self.num_clients):\n            local_data = [random.random() for _ in range(random.randint(50,200))]\n            grad = self.client_train(i, local_data)\n            grads.append(grad)\n        return self.federated_averaging(grads)\n\nif __name__ == \"__main__\":\n    worker = FederatedLearningWorker(num_clients=10)\n    worker.run_round()\n\n[executed on device: 10_3_6_9 (85294689-03d5-431e-abd5-9e27d4c94814)]"}